const prospect = $('When Executed by Another Workflow').item.json;
const settings = $input.item.json;
const linkedinHealth = $('Get LinkedIn Account Health').first().json.health_state;

const fallbackMetadata = ['yellow', 'red'].includes(linkedinHealth)
  ? {
      fallback_reason: 'linkedin_health',
      linkedin_health: linkedinHealth,
      original_channel: 'linkedin',
      actual_channel: 'email'
    }
  : {};

const step = Number(prospect.current_step) + 1;
const firstName = prospect.first_name || 'there';
const company = prospect.company || 'your company';

const senderName = settings.sender_name || 'Outreach Team';
const businessName = settings.business_name || 'Your Company';
const senderEmail = settings.sender_email || 'your-business@email.com';
const unsubscribeUrl = settings.unsubscribe_url || 'https://your-domain.com/unsubscribe';

const scheduling = settings.config.scheduling;
if (!scheduling) {
  throw new Error('Scheduling configuration not found');
}

const timezone = prospect.timezone || scheduling.default_timezone;
const minDays = Number(scheduling.delay_business_days_min);
const maxDays = Number(scheduling.delay_business_days_max);
const startHour = Number(scheduling.business_start_hour);

if (!timezone || minDays < 1 || maxDays < minDays) {
  throw new Error('Invalid scheduling configuration');
}

const templates = {
  1: {
    subject: `Quick introduction for ${company}`,
    message: `Hi ${firstName},<br><br>
I wanted to connect and introduce myself. I came across ${company} and thought there might be an opportunity for us to connect.<br><br>
Would you be open to a brief conversation?`
  },
  2: {
    subject: `Exploring an opportunity with ${company}`,
    message: `Hi ${firstName},<br><br>
I wanted to follow up and explore whether our services could be relevant to ${company}.<br><br>
Would you be available for a short conversation?`
  },
  3: {
    subject: `Following up, ${firstName}`,
    message: `Hi ${firstName},<br><br>
I wanted to follow up on my previous email and see if this is something worth discussing.<br><br>
I'd be happy to share more details.`
  },
  4: {
    subject: `Any thoughts, ${firstName}?`,
    message: `Hi ${firstName},<br><br>
Just checking whether you had a chance to consider my previous message.<br><br>
Would a brief discussion be useful?`
  },
  5: {
    subject: `Closing the loop, ${firstName}`,
    message: `Hi ${firstName},<br><br>
I understand this may not be a priority right now. I'll close the loop here, but you're welcome to reach out if things change.`
  }
};

const template = templates[step];
if (!template) throw new Error(`No email template found for step ${step}`);

function getLocalParts(date, zone) {
  const parts = new Intl.DateTimeFormat('en-US', {
    timeZone: zone,
    year: 'numeric',
    month: 'numeric',
    day: 'numeric'
  }).formatToParts(date);

  const result = {};
  for (const part of parts) {
    if (part.type !== 'literal') result[part.type] = Number(part.value);
  }
  return result;
}

function localTimeToUTC(year, month, day, hour, zone) {
  const target = Date.UTC(year, month - 1, day, hour);
  let guess = target;

  for (let i = 0; i < 4; i++) {
    const local = new Intl.DateTimeFormat('en-US', {
      timeZone: zone,
      year: 'numeric',
      month: 'numeric',
      day: 'numeric',
      hour: 'numeric',
      hourCycle: 'h23'
    }).formatToParts(new Date(guess));

    const p = {};
    for (const part of local) {
      if (part.type !== 'literal') p[part.type] = Number(part.value);
    }

    const represented = Date.UTC(p.year, p.month - 1, p.day, p.hour);
    guess += target - represented;
  }

  return new Date(guess);
}

function calculateNextSend() {
  const delay = Math.floor(Math.random() * (maxDays - minDays + 1)) + minDays;
  const now = new Date();
  const local = getLocalParts(now, timezone);

  const date = new Date(Date.UTC(local.year, local.month - 1, local.day));
  let added = 0;

  while (added < delay) {
    date.setUTCDate(date.getUTCDate() + 1);
    const day = date.getUTCDay();

    if (day !== 0 && day !== 6) added++;
  }

  while (date.getUTCDay() === 0 || date.getUTCDay() === 6) {
    date.setUTCDate(date.getUTCDate() + 1);
  }

  return localTimeToUTC(
    date.getUTCFullYear(),
    date.getUTCMonth() + 1,
    date.getUTCDate(),
    startHour,
    timezone
  ).toISOString();
}

const footer = `
<br><br>
Best regards,<br>
${senderName}<br>
${businessName}<br>
<a href="mailto:${senderEmail}">${senderEmail}</a>
<br><br>
<a href="${unsubscribeUrl}">Unsubscribe</a>
`;

return {
  json: {
    email: prospect.email,
    subject: template.subject,
    message: template.message + footer,
    sender_name: senderName,
    sender_email: senderEmail,
    business_name: businessName,
    prospect_id: prospect.id,
    response: fallbackMetadata,
    action: 'email_sent',
    step,
    next_send_at: step < 5 ? calculateNextSend() : null
  }
};

const prospect = $('When Executed by Another Workflow').item.json;
const config = $input.item.json.config.scheduling;

const step = Number(prospect.current_step) + 1;
const timezone = prospect.timezone || config.default_timezone;

const minDays = Number(config.delay_business_days_min);
const maxDays = Number(config.delay_business_days_max);
const startHour = Number(config.business_start_hour);

if (!timezone || minDays < 1 || maxDays < minDays) {
  throw new Error('Invalid scheduling configuration');
}

function localParts(date) {
  const parts = new Intl.DateTimeFormat('en-US', {
    timeZone: timezone,
    year: 'numeric',
    month: 'numeric',
    day: 'numeric'
  }).formatToParts(date);

  const result = {};
  for (const p of parts) {
    if (p.type !== 'literal') result[p.type] = Number(p.value);
  }
  return result;
}

function localToUTC(year, month, day, hour) {
  const target = Date.UTC(year, month - 1, day, hour);
  let guess = target;

  for (let i = 0; i < 4; i++) {
    const parts = new Intl.DateTimeFormat('en-US', {
      timeZone: timezone,
      year: 'numeric',
      month: 'numeric',
      day: 'numeric',
      hour: 'numeric',
      hourCycle: 'h23'
    }).formatToParts(new Date(guess));

    const p = {};
    for (const part of parts) {
      if (part.type !== 'literal') p[part.type] = Number(part.value);
    }

    guess += target - Date.UTC(p.year, p.month - 1, p.day, p.hour);
  }

  return new Date(guess);
}

function nextSendAt() {
  const delay = Math.floor(Math.random() * (maxDays - minDays + 1)) + minDays;
  const now = localParts(new Date());
  const date = new Date(Date.UTC(now.year, now.month - 1, now.day));

  let added = 0;
  while (added < delay) {
    date.setUTCDate(date.getUTCDate() + 1);
    if (date.getUTCDay() !== 0 && date.getUTCDay() !== 6) added++;
  }

  return localToUTC(
    date.getUTCFullYear(),
    date.getUTCMonth() + 1,
    date.getUTCDate(),
    startHour
  ).toISOString();
}

return {
  json: {
    prospect_id: prospect.id,
    step,
    next_send_at: step < 5 ? nextSendAt() : null,
    status: step === 5 ? 'completed' : 'active'
  }
};

